create table public.gmail_hub_outbox (job_id text primary key,empresa_id uuid not null,status text not null check(status in ('SENDING','SENT','UNCERTAIN')),message_id text,thread_id text,error text,created_at timestamptz not null default now(),updated_at timestamptz not null default now()); alter table public.gmail_hub_outbox enable row level security;revoke all on public.gmail_hub_outbox from public,anon,authenticated;grant all on public.gmail_hub_outbox to service_role;